import sqlite3
import uuid
import difflib
from datetime import datetime, timezone
from flask import Flask, request, jsonify, g, Response, abort, redirect, url_for

app = Flask(__name__)
DATABASE = 'db.sqlite3'


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    with app.app_context():
        db = get_db()
        db.executescript('''
            CREATE TABLE IF NOT EXISTS entries (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                created_by TEXT NOT NULL,
                last_modified_by TEXT NOT NULL,
                last_modified_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS edits (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                entry_id TEXT NOT NULL,
                previous_content TEXT NOT NULL,
                new_content TEXT NOT NULL,
                modified_by TEXT NOT NULL,
                summary TEXT NOT NULL,
                modified_at TEXT NOT NULL,
                FOREIGN KEY (entry_id) REFERENCES entries (id)
            );
        ''')
        db.commit()


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def escape_html(text):
    return (text.replace('&', '&amp;')
                .replace('<', '&lt;')
                .replace('>', '&gt;')
                .replace('"', '&quot;')
                .replace("'", '&#39;'))


def render_page(title, body):
    return f'''<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>{escape_html(title)}</title>
<style>
body {{ font-family: sans-serif; max-width: 900px; margin: 2em auto; padding: 0 1em; }}
h1 {{ border-bottom: 2px solid #333; padding-bottom: 0.3em; }}
.entry-list li {{ margin: 0.5em 0; }}
.meta {{ color: #666; font-size: 0.9em; }}
.content {{ white-space: pre-wrap; background: #f7f7f7; padding: 1em; border-radius: 4px; }}
.diff {{ font-family: monospace; white-space: pre-wrap; background: #f7f7f7; padding: 1em; border-radius: 4px; }}
.add {{ color: green; }}
.del {{ color: red; }}
.edit {{ border: 1px solid #ddd; border-radius: 4px; padding: 1em; margin: 1em 0; }}
a {{ color: #0645ad; }}
</style>
</head>
<body>
{body}
</body>
</html>'''


def entry_to_dict(row):
    return {
        'id': row['id'],
        'title': row['title'],
        'content': row['content'],
        'lastModifiedBy': row['last_modified_by'],
        'lastModifiedAt': row['last_modified_at'],
    }


@app.route('/entries', methods=['GET'])
def list_entries():
    db = get_db()
    rows = db.execute('SELECT * FROM entries ORDER BY title').fetchall()
    items = ''.join(
        f'<li><a href="/entries/{escape_html(r["id"])}">{escape_html(r["title"])}</a> '
        f'<span class="meta">(last modified by {escape_html(r["last_modified_by"])} '
        f'at {escape_html(r["last_modified_at"])})</span></li>'
        for r in rows
    )
    if not items:
        items = '<li>No entries yet.</li>'
    body = f'<h1>Wiki Entries</h1><ul class="entry-list">{items}</ul>'
    return Response(render_page('Wiki Entries', body), mimetype='text/html')


@app.route('/entries', methods=['POST'])
def create_entry():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'error': 'Invalid JSON body'}), 400
    title = data.get('title')
    content = data.get('content')
    created_by = data.get('createdBy')
    if not title or content is None or not created_by:
        return jsonify({'error': 'title, content and createdBy are required'}), 400

    entry_id = uuid.uuid4().hex
    ts = now_iso()
    db = get_db()
    db.execute(
        'INSERT INTO entries (id, title, content, created_by, last_modified_by, last_modified_at) '
        'VALUES (?, ?, ?, ?, ?, ?)',
        (entry_id, title, content, created_by, created_by, ts)
    )
    db.commit()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    return jsonify(entry_to_dict(row)), 201


@app.route('/entries/<entry_id>', methods=['GET'])
def get_entry(entry_id):
    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return Response(render_page('Not Found', '<h1>Entry not found</h1>'), status=404, mimetype='text/html')

    contributors = db.execute(
        'SELECT DISTINCT modified_by FROM edits WHERE entry_id = ? ORDER BY modified_by',
        (entry_id,)
    ).fetchall()
    contributor_names = [c['modified_by'] for c in contributors]
    if row['created_by'] not in contributor_names:
        contributor_names.insert(0, row['created_by'])

    contributors_html = ', '.join(escape_html(c) for c in contributor_names) if contributor_names else 'None'
    body = f'''
<h1>{escape_html(row["title"])}</h1>
<p class="meta">Last modified by {escape_html(row["last_modified_by"])} at {escape_html(row["last_modified_at"])}</p>
<div class="content">{escape_html(row["content"])}</div>
<h2>Contributors</h2>
<p>{contributors_html}</p>
<p><a href="/entries/{escape_html(entry_id)}/edits">View edit history</a></p>
'''
    return Response(render_page(row['title'], body), mimetype='text/html')


@app.route('/entries/<entry_id>', methods=['PUT'])
def update_entry(entry_id):
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'error': 'Invalid JSON body'}), 400
    content = data.get('content')
    modified_by = data.get('modifiedBy')
    summary = data.get('summary')
    if content is None or not modified_by or not summary:
        return jsonify({'error': 'content, modifiedBy and summary are required'}), 400

    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return jsonify({'error': 'Entry not found'}), 404

    ts = now_iso()
    db.execute(
        'INSERT INTO edits (entry_id, previous_content, new_content, modified_by, summary, modified_at) '
        'VALUES (?, ?, ?, ?, ?, ?)',
        (entry_id, row['content'], content, modified_by, summary, ts)
    )
    db.execute(
        'UPDATE entries SET content = ?, last_modified_by = ?, last_modified_at = ? WHERE id = ?',
        (content, modified_by, ts, entry_id)
    )
    db.commit()
    updated = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    return jsonify(entry_to_dict(updated)), 200


@app.route('/entries/<entry_id>/edits', methods=['GET'])
def entry_edits(entry_id):
    db = get_db()
    row = db.execute('SELECT * FROM entries WHERE id = ?', (entry_id,)).fetchone()
    if row is None:
        return Response(render_page('Not Found', '<h1>Entry not found</h1>'), status=404, mimetype='text/html')

    edits = db.execute(
        'SELECT * FROM edits WHERE entry_id = ? ORDER BY modified_at DESC, id DESC',
        (entry_id,)
    ).fetchall()

    if not edits:
        edits_html = '<p>No edits have been made to this entry yet.</p>'
    else:
        parts = []
        for e in edits:
            diff_lines = difflib.unified_diff(
                e['previous_content'].splitlines(),
                e['new_content'].splitlines(),
                fromfile='previous',
                tofile='current',
                lineterm=''
            )
            diff_html_parts = []
            for line in diff_lines:
                esc = escape_html(line)
                if line.startswith('+') and not line.startswith('+++'):
                    diff_html_parts.append(f'<span class="add">{esc}</span>')
                elif line.startswith('-') and not line.startswith('---'):
                    diff_html_parts.append(f'<span class="del">{esc}</span>')
                else:
                    diff_html_parts.append(esc)
            diff_html = '\n'.join(diff_html_parts)
            parts.append(f'''
<div class="edit">
  <p class="meta">Modified by {escape_html(e["modified_by"])} at {escape_html(e["modified_at"])}</p>
  <p><strong>Summary:</strong> {escape_html(e["summary"])}</p>
  <div class="diff">{diff_html}</div>
</div>''')
        edits_html = ''.join(parts)

    body = f'''
<h1>Edit History: {escape_html(row["title"])}</h1>
<p><a href="/entries/{escape_html(entry_id)}">Back to entry</a></p>
{edits_html}
'''
    return Response(render_page(f'Edit History - {row["title"]}', body), mimetype='text/html')


@app.route('/')
def index():
    return redirect(url_for('list_entries'))


init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
